type GatewayType = "stripe" | "paypal" | "razorpay";

function createGateway(type: GatewayType): PaymentGateway {
  switch (type) {
    case "stripe": return new StripeGateway();
    case "paypal": return new PaypalGateway();
    case "razorpay": return new RazorpayGateway();
  }
}

// Every call site, everywhere, just does this:
const gateway = createGateway("stripe");
